def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []   # snapshots taken before successful operations
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None

        # Small chunks avoid Python's limit on converting long digit strings.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if len(parts) != arities.get(verb) or any(p == "" for p in parts):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = parts[1]

        if verb == "open":
            if name in accounts:
                rejected.append(index)
                continue
            updates = {name: (amount, False)}

        else:
            if name not in accounts:
                rejected.append(index)
                continue

            balance, frozen = accounts[name]

            if verb == "deposit":
                updates = {name: (balance + amount, frozen)}

            elif verb == "withdraw":
                if frozen or balance < amount:
                    rejected.append(index)
                    continue
                updates = {name: (balance - amount, frozen)}

            elif verb == "transfer":
                target = parts[2]
                if (
                    target == name
                    or target not in accounts
                    or frozen
                    or balance < amount
                ):
                    rejected.append(index)
                    continue

                target_balance, target_frozen = accounts[target]
                updates = {
                    name: (balance - amount, frozen),
                    target: (target_balance + amount, target_frozen),
                }

            else:
                desired_frozen = verb == "freeze"
                if frozen == desired_frozen:
                    rejected.append(index)
                    continue
                updates = {name: (balance, desired_frozen)}

        history.append(
            tuple((account, accounts.get(account)) for account in updates)
        )
        accounts.update(updates)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
